104	function startSessionMaintenance() {
105	  clearSessionTimers();
106	  const token = getAuthToken();
107	  const exp = token ? decodeJwtExp(token) : null;
108	  if (exp === null) return;
109	
110	  const millisecondsUntilExpiry = exp * 1000 - Date.now();
111	  if (millisecondsUntilExpiry <= 0) {
112	    useAuthStore.getState().requireRelogin();
113	    return;
114	  }
115	
116	  const showWarning = () => {
117	    useAuthStore.setState({ sessionExpiringSoon: true });
118	  };
119	  const refresh = () => {
120	    void useAuthStore.getState().refreshSession();
121	  };
122	
123	  if (millisecondsUntilExpiry <= SESSION_WARNING_MS) {
124	    showWarning();
125	  } else {
126	    sessionWarningTimeout = setTimeout(
127	      showWarning,
128	      millisecondsUntilExpiry - SESSION_WARNING_MS,
129	    );
130	  }
131	
132	  sessionRefreshTimeout = setTimeout(
133	    refresh,
134	    Math.max(0, millisecondsUntilExpiry - SESSION_REFRESH_AHEAD_MS),
135	  );
136	}
