407	async function runAccountOperation<T>(
408	  set: (partial: Partial<AuthState>) => void,
409	  operation: Exclude<AccountOperation, "idle">,
410	  action: () => Promise<T>,
411	): Promise<T> {
412	  set({ accountOperation: operation, accountError: null });
413	  try {
414	    return await action();
415	  } catch (error) {
416	    const accountError =
417	      error instanceof Error ? error.message : "Unknown error";
418	    set({ accountError });
419	    throw error;
420	  } finally {
421	    set({ accountOperation: "idle" });
422	  }
423	}
