1	/**
2	 * Thin fetch wrapper for the FastAPI backend.
3	 *
4	 * The JWT is kept in a module-level variable (mirrored to localStorage) so the
5	 * client has no import cycle with the auth store. A single `onUnauthorized`
6	 * callback lets the auth layer react to expired/invalid tokens globally.
7	 */
8	
9	const API_BASE = import.meta.env.VITE_API_BASE_URL || "/api";
10	const TOKEN_KEY = "ft_token";
11	
12	/** Hang ceiling for a staged file upload — bounds a stalled/dead connection,
13	 *  not the time a large-but-healthy transfer may take. */
14	export const UPLOAD_STAGE_TIMEOUT_MS = 120_000;
15	
16	let authToken: string | null = localStorage.getItem(TOKEN_KEY);
17	let unauthorizedHandler: (() => void) | null = null;
18	
19	// In-memory only (never persisted): the short-lived unlock token proving a
20	// visitor entered the correct password for a password-protected public tree.
21	// A page refresh drops it and re-prompts — acceptable, and safer than
22	// persisting it alongside the JWT.
23	let publicTreeToken: string | null = null;
24	
25	export function setPublicTreeToken(token: string | null) {
26	  publicTreeToken = token;
27	}
28	
29	/** The in-memory password-unlock token used for public-tree requests. */
30	export function getPublicTreeToken(): string | null {
31	  return publicTreeToken;
32	}
33	
34	export function setAuthToken(token: string | null) {
35	  authToken = token;
36	  if (token) {
37	    localStorage.setItem(TOKEN_KEY, token);
38	  } else {
39	    localStorage.removeItem(TOKEN_KEY);
40	  }
41	}
42	
43	export function getAuthToken(): string | null {
44	  return authToken;
45	}
46	
47	export function onUnauthorized(handler: () => void) {
48	  unauthorizedHandler = handler;
49	}
50	
51	export class ApiError extends Error {
52	  status: number;
53	  constructor(status: number, message: string) {
54	    super(message);
55	    this.status = status;
56	  }
57	}
58	
59	interface RequestOptions {
60	  params?: Record<string, string | number | boolean | undefined | null>;
61	  body?: unknown;
62	  formData?: FormData;
63	  raw?: boolean;
64	  signal?: AbortSignal;
65	  timeoutMs?: number;
66	}
67	
68	function buildUrl(path: string, params?: RequestOptions["params"]): string {
69	  const url = `${API_BASE}${path}`;
70	  if (!params) return url;
71	  const search = new URLSearchParams();
72	  Object.entries(params).forEach(([key, value]) => {
73	    if (value !== undefined && value !== null)
74	      search.append(key, String(value));
75	  });
76	  const qs = search.toString();
77	  return qs ? `${url}?${qs}` : url;
78	}
79	
80	async function request<T>(
81	  method: string,
82	  path: string,
83	  options: RequestOptions = {},
84	): Promise<T> {
85	  const headers: Record<string, string> = {};
86	  if (authToken) headers["Authorization"] = `Bearer ${authToken}`;
87	  if (publicTreeToken) headers["X-Public-Tree-Token"] = publicTreeToken;
88	
89	  let payload: BodyInit | undefined;
90	  if (options.formData) {
91	    payload = options.formData;
92	  } else if (options.body !== undefined) {
93	    headers["Content-Type"] = "application/json";
94	    payload = JSON.stringify(options.body);
95	  }
96	
97	  // A hung connection (dead keep-alive socket, dropped wifi, ...) otherwise
98	  // leaves fetch() pending forever with no error — this is a ceiling on that
99	  // hang, not a body-transfer deadline, so it must stay generous enough for a
100	  // full upload on a slow link.
101	  let timeoutController: AbortController | undefined;
102	  let timeoutId: ReturnType<typeof setTimeout> | undefined;
103	  let signal = options.signal;
104	  if (options.timeoutMs !== undefined) {
105	    timeoutController = new AbortController();
106	    timeoutId = setTimeout(() => timeoutController?.abort(), options.timeoutMs);
107	    options.signal?.addEventListener("abort", () => timeoutController?.abort());
108	    signal = timeoutController.signal;
109	  }
110	
111	  let response: Response;
112	  try {
113	    response = await fetch(buildUrl(path, options.params), {
114	      method,
115	      headers,
116	      body: payload,
117	      signal,
118	    });
119	  } finally {
120	    if (timeoutId !== undefined) clearTimeout(timeoutId);
121	  }
122	
123	  if (response.status === 401) {
124	    unauthorizedHandler?.();
125	  }
126	
127	  if (!response.ok) {
128	    let detail = response.statusText;
129	    try {
130	      const data = await response.json();
131	      detail = data.detail || detail;
132	    } catch {
133	      // non-JSON error body
134	    }
135	    throw new ApiError(response.status, detail);
136	  }
137	
138	  if (options.raw) return response as unknown as T;
139	  if (response.status === 204) return undefined as T;
140	  return (await response.json()) as T;
141	}
142	
143	export const api = {
144	  get: <T>(path: string, params?: RequestOptions["params"]) =>
145	    request<T>("GET", path, { params }),
146	  post: <T>(path: string, body?: unknown, signal?: AbortSignal) =>
147	    request<T>("POST", path, { body, signal }),
148	  put: <T>(path: string, body?: unknown) => request<T>("PUT", path, { body }),
149	  patch: <T>(path: string, body?: unknown) =>
150	    request<T>("PATCH", path, { body }),
151	  del: <T>(path: string, params?: RequestOptions["params"]) =>
152	    request<T>("DELETE", path, { params }),
153	  postForm: <T>(path: string, formData: FormData, timeoutMs?: number) =>
154	    request<T>("POST", path, { formData, timeoutMs }),
155	  getRaw: (path: string, params?: RequestOptions["params"]) =>
156	    request<Response>("GET", path, { params, raw: true }),
157	  postRaw: (path: string, body?: unknown) =>
158	    request<Response>("POST", path, { body, raw: true }),
159	};
